function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').style.opacity=1;toastTimer=setTimeout(()=>$('#toast').style.opacity=0,3800);}
function collect(id){if(testStart)return;examples.add(id);paintScreen();updateUI();toast(items.find(i=>i.id===id).name+' added to the team’s examples.');}
function train(){if(examples.size<2){toast('Collect at least two examples first. Include an apple and another kind of object.');return;}const selected=items.filter(i=>examples.has(i.id));if(!selected.some(i=>i.label)||!selected.some(i=>!i.label)){toast('Include an apple and an object that is not an apple.');return;}trained=selected.map(i=>({...i,features:[...i.features]}));testResult=null;paintScreen();updateUI();toast('R0 learned from '+trained.length+' examples. Try an object it has not seen.');}
function classify(item){if(!trained?.length)return null;return [...trained].sort((a,b)=>distance(a.features,item.features)-distance(b.features,item.features))[0].label;}
function distance(a,b){return a.reduce((sum,v,i)=>sum+(v-b[i])**2,0);}
function runTest(){if(!trained){toast('Train R0 before running the test.');return;}if(testStart)return;testResult=null;scene.getObjectByName('testapple').position.set(4.9,.3,2);testStart=performance.now();updateUI();toast('Watch R0 classify a green apple and choose its delivery bay.');}
