function updateUI(){const c=copy[view];$('#chapter').textContent=c.chapter;$('#heading').innerHTML=c.heading;$('#description').textContent=c.description;$('#instruction').textContent=c.instruction;$('#learning').textContent=c.learning;document.querySelectorAll('[data-scene]').forEach(b=>{b.classList.toggle('active',b.dataset.scene===view);b.setAttribute('aria-current',String(b.dataset.scene===view));});const list=items.map(i=>`<button class="sample ${examples.has(i.id)?'chosen':''}" data-item="${i.id}" style="--swatch:${i.color}" aria-pressed="${examples.has(i.id)}"><i></i>${i.name}${examples.has(i.id)?' ✓':''}</button>`).join('');$('#task-controls').innerHTML=view==='collect'?`<div class="sample-list">${list}</div><div class="metric"><span>Team examples</span><strong>${examples.size} / 5</strong></div><button class="primary" data-go="train">Go to training station →</button>`:view==='train'?`<div class="sample-list">${items.filter(i=>examples.has(i.id)).map(i=>`<span class="sample chosen" style="--swatch:${i.color}"><i></i>${i.name}</span>`).join('')||'<p>No examples collected yet.</p>'}</div><div class="metric"><span>Model</span><strong>${trained?'Trained on '+trained.length+' examples':'Not trained yet'}</strong></div><button class="primary" id="train">${trained?'Retrain R0':'Train R0'}</button><button class="secondary" data-go="test">Visit the test course →</button>`:`${testResult!==null?`<div class="result ${testResult?'success':''}">${testResult?'✓ Correct delivery. Adding variety improved R0’s prediction.':'R0 sent the green apple to OTHER ITEMS. Its training examples were missing something.'}</div>`:''}<div class="metric"><span>New test object</span><strong>Green apple</strong></div><button class="primary" id="run" ${testStart?'disabled':''}>${testStart?'R0 is testing…':'▶ Run the delivery test'}</button><button class="secondary" data-go="collect">Improve the examples ↶</button>`;document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>collect(b.dataset.item));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>setScene(b.dataset.go));if($('#train'))$('#train').onclick=train;if($('#run'))$('#run').onclick=runTest;}
function setScene(next,instant=false){view=next;const mobile=innerWidth<680;const presets=mobile?{collect:{eye:[5,6.5,12],target:[-2.3,1.1,0]},train:{eye:[5.3,4.1,9],target:[.3,2,-2]},test:{eye:[12,7,12],target:[4.8,.7,-.3]}}:{collect:{eye:[10.8,6.7,14],target:[-.4,1.1,-.6]},train:{eye:[6.8,4.7,7.7],target:[.5,1.8,-2]},test:{eye:[13.8,8.7,11.5],target:[4.8,.6,-.8]}};const p=presets[next],offset=role==='parent'?-2:0;const eye=new THREE.Vector3(p.eye[0]+offset,p.eye[1]+(role==='parent'?1:0),p.eye[2]);if(instant){camera.position.copy(eye);controls.target.set(...p.target);controls.update();}else cameraTween={start:performance.now(),from:camera.position.clone(),to:eye,targetFrom:controls.target.clone(),targetTo:new THREE.Vector3(...p.target)};updateUI();}
function resize(){const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;if(w<680)camera.setViewOffset(w,h,0,h*.2,w,h);else camera.clearViewOffset();camera.updateProjectionMatrix();}window.addEventListener('resize',()=>{resize();if(loaded)setScene(view,true);});resize();
let pointerDown;canvas.addEventListener('pointerdown',e=>pointerDown={x:e.clientX,y:e.clientY});canvas.addEventListener('pointerup',e=>{if(!pointerDown||Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)>7)return;const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(clickables,false)[0];if(hit){if(view==='collect')collect(hit.object.userData.item);else toast('Collect examples at the collection bench.');}});
canvas.addEventListener('pointermove',e=>{if(!loaded)return;const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);canvas.style.cursor=ray.intersectObjects(clickables,false).length&&view==='collect'?'pointer':'grab';});controls.addEventListener('start',()=>cameraTween=null);
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>setScene(b.dataset.scene));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{role=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));setScene(view);});$('#help').onclick=()=>$('#help-dialog').showModal();$('#credits-button').onclick=()=>$('#credits-dialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#full').onclick=async()=>{if(document.fullscreenElement)await document.exitFullscreen();else if($('#academy').requestFullscreen)await $('#academy').requestFullscreen();};
function frame(now){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(document.hidden)return;if(cameraTween){const t=Math.min(1,(now-cameraTween.start)/1250),e=t*t*(3-2*t);camera.position.lerpVectors(cameraTween.from,cameraTween.to,e);controls.target.lerpVectors(cameraTween.targetFrom,cameraTween.targetTo,e);if(t===1)cameraTween=null;}mixers.forEach(m=>m.update(dt));if(testStart&&robots[0]){const t=Math.min(1,(now-testStart)/7000),prediction=classify(items[2]),destination=prediction?4:6;robots[0].position.set(t<.5?THREE.MathUtils.lerp(1.1,4.9,t*2):THREE.MathUtils.lerp(4.9,destination,(t-.5)*2),0,THREE.MathUtils.lerp(.4,-3.2,t));robots[0].rotation.y=Math.PI;const apple=scene.getObjectByName('testapple');if(t>.25){apple.position.set(robots[0].position.x,.85,robots[0].position.z+.35);}const rlabel=scene.getObjectByName('r0label');rlabel.position.set(robots[0].position.x,2.27,robots[0].position.z);if(t===1){testStart=0;testResult=prediction===1;updateUI();toast(testResult?'R0 delivered the green apple correctly!':'A mistake we can learn from. Show R0 a green apple, then retrain.');}}controls.update();for(const name of ['r0label','botlabel']){const l=scene.getObjectByName(name);if(l)l.quaternion.copy(camera.quaternion);}for(const name of ['r0label','botlabel']){const l=scene.getObjectByName(name);if(l)l.quaternion.copy(camera.quaternion);}renderer.render(scene,camera);}requestAnimationFrame(frame);
load().catch(error=>{console.error(error);$('#loading').innerHTML='<b>Preview could not load.</b><p>'+error.message+'</p><p>This preview requires WebGL and local assets.</p>';});
